import { useState, useEffect } from 'react';
import { Card, Button, message, Row, Col, Space, Tag, List, Typography, Form, Input } from 'antd';
import { EyeOutlined, CheckOutlined, SaveOutlined } from '@ant-design/icons';
import { fetchPatients, updatePatient, createExamination } from '../lib/api';
import { CallAndPrintButton } from '../components/CallAndPrintButton';
import dayjs from 'dayjs';

const { Title, Text } = Typography;

export function ExaminationPage() {
  const [waitingPatients, setWaitingPatients] = useState([]);
  const [inProgressPatients, setInProgressPatients] = useState([]);
  const [completedPatients, setCompletedPatients] = useState([]);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [loading, setLoading] = useState(false);
  const [form] = Form.useForm();

  useEffect(() => {
    loadPatients();
    const interval = setInterval(loadPatients, 30000); // Refresh every 30s
    return () => clearInterval(interval);
  }, []);

  const loadPatients = async () => {
    try {
      // Load patients with visitPurpose including 'examination'
      const data = await fetchPatients('', 'examination', '');

      setWaitingPatients(data.filter(p => p.examinationStatus === 'waiting'));
      setInProgressPatients(data.filter(p => p.examinationStatus === 'in_progress'));
      setCompletedPatients(data.filter(p => p.examinationStatus === 'completed'));
    } catch (error) {
      message.error('Không thể tải danh sách bệnh nhân');
    }
  };

  const handleCallAndSelect = async (patient) => {
    setSelectedPatient(patient);
    form.resetFields();

    // Update patient status to in_progress when called
    if (patient.examinationStatus === 'waiting') {
      try {
        await updatePatient(patient.id, {
          examinationStatus: 'in_progress',
          visitStatus: 'in_progress' // Also update overall visit status
        });
        message.success(`Đã gọi ${patient.fullName} vào phòng khám bệnh`);
        await loadPatients(); // Ensure immediate reload
      } catch (error) {
        console.error('Failed to update patient status');
      }
    }
  };

  const handleSelectPatient = async (patient) => {
    setSelectedPatient(patient);
    form.resetFields();

    // Update patient status to in_progress if waiting
    if (patient.examinationStatus === 'waiting') {
      try {
        await updatePatient(patient.id, {
          examinationStatus: 'in_progress',
          visitStatus: 'in_progress' // Also update overall visit status
        });
        await loadPatients(); // Ensure immediate reload
      } catch (error) {
        console.error('Failed to update patient status');
      }
    }
  };

  const handleSaveExamination = async (values) => {
    if (!selectedPatient) {
      message.warning('Vui lòng chọn bệnh nhân');
      return;
    }

    try {
      setLoading(true);

      // Create examination record
      const examinationData = {
        patientId: selectedPatient.id,
        ...values,
        examDate: new Date().toISOString()
      };

      await createExamination(examinationData);

      // Update patient status to completed for examination
      await updatePatient(selectedPatient.id, {
        examinationStatus: 'completed',
        visitStatus: 'completed' // Also update overall visit status
      });

      message.success('Đã lưu kết quả khám bệnh');

      form.resetFields();
      setSelectedPatient(null);
      loadPatients();
    } catch (error) {
      message.error('Không thể lưu kết quả khám');
    } finally {
      setLoading(false);
    }
  };

  const renderPatientList = (patients, showCallButton = false) => (
    <List
      dataSource={patients}
      pagination={false}
      renderItem={(patient) => (
        <List.Item
          key={patient.id}
          style={{
            cursor: 'pointer',
            background: selectedPatient?.id === patient.id ? '#e6f7ff' : 'white',
            padding: '6px',
            borderRadius: '4px',
            marginBottom: '6px',
            border: selectedPatient?.id === patient.id ? '2px solid #1890ff' : '1px solid #d9d9d9',
            transition: 'all 0.2s'
          }}
          onClick={() => handleSelectPatient(patient)}
        >
          <div style={{ width: '100%' }}>
            <div style={{ marginBottom: '4px', textAlign: 'center' }}>
              <Tag color="red" style={{ fontSize: '12px', fontWeight: 'bold', margin: '0 0 4px 0' }}>
                {patient.queueNumber || '-'}
              </Tag>
            </div>
            <div style={{ textAlign: 'center', marginBottom: '4px' }}>
              <Text strong style={{ fontSize: '12px' }}>{patient.fullName}</Text>
            </div>
            <div style={{ fontSize: '10px', textAlign: 'center', marginBottom: '2px' }}>
              <Text type="secondary">SĐT: </Text>
              <Text>{patient.phone || '-'}</Text>
            </div>
            <div style={{ fontSize: '10px', textAlign: 'center', marginBottom: '4px' }}>
              <Text type="secondary">TL: </Text>
              <Text strong>{patient.initialVaOd || '?'} / {patient.initialVaOs || '?'}</Text>
            </div>
            {showCallButton && (
              <div style={{ textAlign: 'center', marginTop: '4px' }}>
                <CallAndPrintButton
                  patient={patient}
                  destination="khám bệnh"
                  size="small"
                  onSuccess={() => handleCallAndSelect(patient)}
                />
              </div>
            )}
          </div>
        </List.Item>
      )}
      locale={{ emptyText: <div style={{ textAlign: 'center', padding: '10px', color: '#999', fontSize: '11px' }}>Không có bệnh nhân</div> }}
    />
  );

  return (
    <div>
      <Row gutter={16}>
        {/* Left: Patient lists - 3 columns for 3 statuses */}
        <Col xs={24} lg={10}>
          <Row gutter={[8, 8]}>
            {/* Chờ khám */}
            <Col span={8}>
              <Card
                size="small"
                title={
                  <div style={{ fontSize: '13px', fontWeight: 'bold', textAlign: 'center' }}>
                    <EyeOutlined /> Chờ khám <Tag color="orange">{waitingPatients.length}</Tag>
                  </div>
                }
                bordered={true}
                headStyle={{ background: '#fff7e6', borderBottom: '2px solid #ffa940' }}
                bodyStyle={{ padding: '8px', maxHeight: '75vh', overflowY: 'auto' }}
              >
                {renderPatientList(waitingPatients, true)}
              </Card>
            </Col>

            {/* Đang khám */}
            <Col span={8}>
              <Card
                size="small"
                title={
                  <div style={{ fontSize: '13px', fontWeight: 'bold', textAlign: 'center' }}>
                    <EyeOutlined /> Đang khám <Tag color="blue">{inProgressPatients.length}</Tag>
                  </div>
                }
                bordered={true}
                headStyle={{ background: '#e6f7ff', borderBottom: '2px solid #1890ff' }}
                bodyStyle={{ padding: '8px', maxHeight: '75vh', overflowY: 'auto' }}
              >
                {renderPatientList(inProgressPatients)}
              </Card>
            </Col>

            {/* Hoàn thành */}
            <Col span={8}>
              <Card
                size="small"
                title={
                  <div style={{ fontSize: '13px', fontWeight: 'bold', textAlign: 'center' }}>
                    <CheckOutlined /> Hoàn thành <Tag color="green">{completedPatients.length}</Tag>
                  </div>
                }
                bordered={true}
                headStyle={{ background: '#f6ffed', borderBottom: '2px solid #52c41a' }}
                bodyStyle={{ padding: '8px', maxHeight: '75vh', overflowY: 'auto' }}
              >
                {renderPatientList(completedPatients)}
              </Card>
            </Col>
          </Row>
        </Col>

        {/* Right: Examination form */}
        <Col xs={24} lg={14}>
          {selectedPatient ? (
            <Card
              title={
                <Space>
                  <EyeOutlined style={{ fontSize: '20px', color: '#1890ff' }} />
                  <span style={{ fontSize: '18px', fontWeight: 'bold' }}>Khám bệnh</span>
                  <span style={{ fontSize: '14px', color: '#999' }}>|</span>
                  <Text strong style={{ fontSize: '16px' }}>{selectedPatient.fullName}</Text>
                  <Tag color="blue">{selectedPatient.code}</Tag>
                  <Tag color="red" style={{ fontSize: '14px', fontWeight: 'bold' }}>{selectedPatient.queueNumber}</Tag>
                </Space>
              }
              extra={
                <Button
                  type="primary"
                  icon={<SaveOutlined />}
                  onClick={() => form.submit()}
                  loading={loading}
                  size="large"
                  style={{ height: '40px', fontSize: '16px', padding: '0 24px' }}
                  disabled={selectedPatient.examinationStatus === 'completed'}
                >
                  Lưu kết quả
                </Button>
              }
              headStyle={{ background: '#f0f5ff', borderBottom: '2px solid #1890ff' }}
            >
              {/* Patient info */}
              <Card size="small" style={{ marginBottom: 16, background: '#f0f5ff' }}>
                <Row gutter={16}>
                  <Col span={6}>
                    <Text strong>Giới tính:</Text> {selectedPatient.gender === 'male' ? 'Nam' : selectedPatient.gender === 'female' ? 'Nữ' : 'Khác'}
                  </Col>
                  <Col span={6}>
                    <Text strong>Ngày sinh:</Text> {selectedPatient.birthDate ? dayjs(selectedPatient.birthDate).format('DD/MM/YYYY') : '-'}
                  </Col>
                  <Col span={6}>
                    <Text strong>SĐT:</Text> {selectedPatient.phone || '-'}
                  </Col>
                  <Col span={6}>
                    <Text strong>Thị lực:</Text> {selectedPatient.initialVaOd || '?'} / {selectedPatient.initialVaOs || '?'}
                  </Col>
                </Row>
                <Row style={{ marginTop: 8 }}>
                  <Col span={24}>
                    <Text strong>Lý do khám:</Text> {selectedPatient.visitReason || '-'}
                  </Col>
                </Row>
              </Card>

              <Form form={form} layout="vertical" onFinish={handleSaveExamination}>
                <Card size="small" style={{ marginBottom: 16 }}>
                  <Form.Item
                    label={<span style={{ fontSize: '16px', fontWeight: 'bold' }}>Triệu chứng</span>}
                    name="symptoms"
                    rules={[{ required: true, message: 'Vui lòng nhập triệu chứng' }]}
                  >
                    <Input.TextArea
                      rows={4}
                      placeholder="Mô tả triệu chứng của bệnh nhân..."
                      style={{ fontSize: '14px' }}
                    />
                  </Form.Item>

                  <Form.Item
                    label={<span style={{ fontSize: '16px', fontWeight: 'bold' }}>Chẩn đoán</span>}
                    name="diagnosis"
                    rules={[{ required: true, message: 'Vui lòng nhập chẩn đoán' }]}
                  >
                    <Input.TextArea
                      rows={4}
                      placeholder="Chẩn đoán bệnh..."
                      style={{ fontSize: '14px' }}
                    />
                  </Form.Item>

                  <Form.Item
                    label={<span style={{ fontSize: '16px', fontWeight: 'bold' }}>Điều trị</span>}
                    name="treatment"
                  >
                    <Input.TextArea
                      rows={4}
                      placeholder="Phương pháp điều trị..."
                      style={{ fontSize: '14px' }}
                    />
                  </Form.Item>

                  <Form.Item
                    label={<span style={{ fontSize: '16px', fontWeight: 'bold' }}>Thuốc kê đơn</span>}
                    name="medications"
                  >
                    <Input.TextArea
                      rows={5}
                      placeholder="Danh sách thuốc và liều lượng..."
                      style={{ fontSize: '14px' }}
                    />
                  </Form.Item>
                </Card>
              </Form>
            </Card>
          ) : (
            <Card style={{ minHeight: '80vh' }}>
              <div style={{ textAlign: 'center', padding: '60px 20px', color: '#999' }}>
                <EyeOutlined style={{ fontSize: 64, marginBottom: 16 }} />
                <Title level={3}>Chọn bệnh nhân từ danh sách bên trái để bắt đầu khám</Title>
                <Text type="secondary">Bệnh nhân sẽ tự động chuyển sang trạng thái "Đang khám" khi được chọn</Text>
              </div>
            </Card>
          )}
        </Col>
      </Row>
    </div>
  );
}